schema:
CREATE TABLE #Participants (learner_id int PRIMARY KEY);
CREATE TABLE #Assessments (
    assessment_id int PRIMARY KEY,
    required bit NOT NULL,
    pass_score int NOT NULL CHECK (pass_score BETWEEN 0 AND 100)
);
CREATE TABLE #Attempts (
    learner_id int NOT NULL,
    assessment_id int NOT NULL,
    attempt_no int NOT NULL CHECK (attempt_no > 0),
    score int NULL CHECK (score BETWEEN 0 AND 100),
    PRIMARY KEY (learner_id, assessment_id, attempt_no)
);

